			*outL2 = bufferTool_satAdd32(*outL2, (sample_mx_t)((float)sm * panL));
			outL2 += 2;
			*outR2 = bufferTool_satAdd32(*outR2, (sample_mx_t)((float)sm * panR));
			outR2 += 2;
